mapper.select:
SELECT h.id, h.course_id AS courseId, c.name AS courseName, h.teacher_id AS teacherId, u.real_name AS teacherName, h.title, h.content, h.attachment_url AS attachmentUrl, h.attachment_name AS attachmentName, h.deadline, h.status, h.create_time AS createTime, (SELECT COUNT(*) FROM homework_submission hs WHERE hs.homework_id = h.id AND hs.status = 1) AS submissionCount, (SELECT COUNT(*) FROM homework_submission hs WHERE hs.homework_id = h.id AND hs.status = 1 AND hs.score IS NOT NULL) AS gradedCount FROM homework h INNER JOIN course c ON h.course_id = c.id LEFT JOIN sys_user u ON h.teacher_id = u.id WHERE h.status = 1
AND h.teacher_id = #{dto.teacherId}
AND h.course_id = #{dto.courseId}
AND h.title LIKE CONCAT('%', #{dto.title}, '%')
ORDER BY h.create_time DESC
